using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId, apiKey));

builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var tools = new[]
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research agent. Given a topic, search the web for information, "
    + "take notes on key findings, then provide a comprehensive summary. "
    + "Always search for multiple aspects of the topic and save important findings as notes before summarizing.");

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [.. tools],
};

Console.WriteLine("Research Agent Ready!");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.WriteLine();

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    researchTools.ClearNotes();

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic thoroughly: {topic}"),
    };

    var invokeOptions = new AgentInvokeOptions
    {
        MaximumIterations = 10,
    };

    Console.WriteLine($"\nResearching '{topic}'...\n");

    await foreach (var message in agent.InvokeStreamingAsync(history, chatOptions, invokeOptions))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n");
}

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a query. Returns relevant search result snippets.")]
    public string SearchWeb([Description("The search query")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (e.g., Bing Search API) for production use.
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        return $"""
            Search results for "{query}":
            1. Wikipedia: {query} is a widely discussed topic with multiple facets covering history, current developments, and future implications.
            2. Research Paper: Recent studies on {query} suggest significant advancements in the field, with key contributors publishing findings in 2025-2026.
            3. News Article: Latest developments in {query} show growing industry interest and investment, with several major companies announcing initiatives.
            4. Expert Analysis: Domain experts note that {query} has both opportunities and challenges that need careful consideration.
            """;
    }

    [Description("Save a research note for later reference when compiling the summary.")]
    public string SaveNote([Description("The note content to save")] string content)
    {
        _notes.Add(content);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    public void ClearNotes() => _notes.Clear();
}

